var a=`1274-saltfish-and-chop-up`;var t=`world-1274`;var n=`AG`;var o=`central-america-caribbean`;var s=4;var r=1475;var d={en:`Saltfish and Chop-Up`,ua:`Солона риба з овочами`};var h={en:`Saltfish and Chop-Up is a dish from Antigua and Barbuda featuring salt cod, spinach, pumpkin, okra. This home-sized recipe records each ingredient at the step where it is used. Cooked spinach stands in for chopped local leafy greens; salt cod must be properly desalinated.`,ua:`Солона риба з овочами, страва кухні країни Антигуа і Барбуда з такими основними складниками: солона тріска, шпинат, гарбуз, бамія. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Приготований шпинат замінює місцеву зелень; солону тріску необхідно правильно вимочити.`};var l=[{en:`Soak salt cod in cold water in the refrigerator for about 24 hours, changing the water several times. Drain before simmering; never soak salted fish at room temperature.`,ua:`Вимочуйте солону тріску в холодній воді в холодильнику близько доби, кілька разів змінюючи воду. Злийте перед варінням; не вимочуйте рибу за кімнатної температури.`,t:[`soaking-dried-produce`],m:1440,i:[[`salt-cod`,540,`g`],[`water`,1500,`ml`]]},{en:`Gently cook the prepared contents in the simmering liquid from earlier steps until fully cooked and safe to eat.`,ua:`Обережно доведіть підготовлені продукти до повної готовності в гарячій рідині з попередніх етапів.`,t:[`poaching`],m:14,i:[]},{en:`Flake the thoroughly cooked, desalted cod with a fork; remove every bone and keep the fish ready for the mixture.`,ua:`Розберіть повністю приготовану вимочену тріску виделкою на дрібні шматочки, видаліть усі кістки й залиште рибу для суміші.`,t:[`shredding`,`mixing`],m:7,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`spinach`,340,`g`],[`pumpkin`,260,`g`],[`okra`,200,`g`],[`yellow-onion`,150,`g`],[`coconut-oil`,40,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,1,`pcs`]]}];var u={slug:a,id:t,country:`AG`,region:o,servings:4,minutes:r,title:d,text:h,steps:l};export{n as country,u as default,t as id,r as minutes,o as region,s as servings,a as slug,l as steps,h as text,d as title};